layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); border-left: 8px solid rgb(142, 144, 140); border-radius: 4px; font-family: var(--ryt-font-body); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 32px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 700; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 16px; padding-bottom: 8px; padding-left: 16px; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-body); font-weight: 400; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-body); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-text); font-family: var(--ryt-font-body); font-size: 14.4px; font-weight: 400; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 700; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #3e999f }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { color: #3e999f; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="nav"] a:hover { background-color: rgb(238, 238, 238); color: #3e999f; color: #4d4d4c }
[data-ryt="brand"]:hover { background-color: rgb(238, 238, 238); color: #3e999f; color: #4d4d4c }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #3e999f }
